import '../models/graph_edge.dart';
import '../models/graph_node.dart';
import '../models/source_location.dart';

/// Structured response generated by [QueryEngine].
class QueryResult {
  final String query;
  final String intent;
  final String title;
  final String summary;
  final String? directAnswer;
  final SourceLocation? sourceLocation;
  final List<GraphNode> dependsOn;
  final List<GraphNode> calls;
  final List<GraphNode> usedBy;
  final List<String> callChain;
  final List<GraphNode> nodes;
  final List<GraphEdge> edges;
  final List<String> suggestedFollowups;

  const QueryResult({
    required this.query,
    required this.intent,
    required this.title,
    required this.summary,
    this.directAnswer,
    this.sourceLocation,
    this.dependsOn = const [],
    this.calls = const [],
    this.usedBy = const [],
    this.callChain = const [],
    this.nodes = const [],
    this.edges = const [],
    this.suggestedFollowups = const [],
  });

  Map<String, dynamic> toJson() => {
        'query': query,
        'intent': intent,
        'title': title,
        'summary': summary,
        'directAnswer': directAnswer,
        'sourceLocation': sourceLocation?.toJson(),
        'dependsOn': dependsOn.map((n) => n.toJson()).toList(),
        'calls': calls.map((n) => n.toJson()).toList(),
        'usedBy': usedBy.map((n) => n.toJson()).toList(),
        'callChain': callChain,
        'nodes': nodes.map((n) => n.toJson()).toList(),
        'edges': edges.map((e) => e.toJson()).toList(),
        'suggestedFollowups': suggestedFollowups,
      };

  factory QueryResult.fromJson(Map<String, dynamic> json) {
    return QueryResult(
      query: json['query'] as String,
      intent: json['intent'] as String,
      title: json['title'] as String,
      summary: json['summary'] as String,
      directAnswer: json['directAnswer'] as String?,
      sourceLocation: json['sourceLocation'] != null
          ? SourceLocation.fromJson(
              json['sourceLocation'] as Map<String, dynamic>)
          : null,
      dependsOn: (json['dependsOn'] as List<dynamic>?)
              ?.map((n) => GraphNode.fromJson(n as Map<String, dynamic>))
              .toList() ??
          const [],
      calls: (json['calls'] as List<dynamic>?)
              ?.map((n) => GraphNode.fromJson(n as Map<String, dynamic>))
              .toList() ??
          const [],
      usedBy: (json['usedBy'] as List<dynamic>?)
              ?.map((n) => GraphNode.fromJson(n as Map<String, dynamic>))
              .toList() ??
          const [],
      callChain: (json['callChain'] as List<dynamic>?)
              ?.map((s) => s as String)
              .toList() ??
          const [],
      nodes: (json['nodes'] as List<dynamic>?)
              ?.map((n) => GraphNode.fromJson(n as Map<String, dynamic>))
              .toList() ??
          const [],
      edges: (json['edges'] as List<dynamic>?)
              ?.map((e) => GraphEdge.fromJson(e as Map<String, dynamic>))
              .toList() ??
          const [],
      suggestedFollowups: (json['suggestedFollowups'] as List<dynamic>?)
              ?.map((s) => s as String)
              .toList() ??
          const [],
    );
  }
}
